import {COLS,ROWS,PATTERNS,neighbors,evolve,stamp} from './life.js';
import {project,unproject,makeWorld,drawDistant,drawPerson,atlasFrames,tile} from './world.js';
const $=s=>document.querySelector(s),canvas=$('#scene'),ctx=canvas.getContext('2d');
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let board=new Uint8Array(COLS*ROWS),people=new Map(),departing=[],serial=0,generation=0,paused=reduced,observing=false,selected=null,hovered=null,tool='observe',pattern='block',lastTick=performance.now(),W=0,H=0,base=1,zoom=1,view={x:54,y:300};
let hoverCell=null,near=false,mid=false,dialogueKeys=[],lastSpeechKey='',pinch=null,pinchUsed=false;
const world=makeWorld(),atlas={image:new Image(),frames:null};atlas.image.onload=()=>{atlas.frames=atlasFrames(atlas.image)};atlas.image.src='assets/children-original.png';
const bubbles=Array.from({length:3},()=>{const div=document.createElement('div');div.className='bubble';$('#speech').append(div);return div});
const phrases=[['这次一起跳？','等一下，我准备好啦！','好，一起！'],['看，我转了一圈。','换我试试看！','我给你数着。'],['你站这边，我站那边。','这样就排好啦。','下一轮会变成什么？'],['我们再玩一轮？','好呀，轮到你啦！','我也来！']];
function scale(){return base*zoom}
function screen(wx,wy){const s=scale();return{x:W/2+(wx-view.x)*s,y:H*.51+(wy-view.y)*s}}
function worldAt(x,y){const s=scale();return{x:view.x+(x-W/2)/s,y:view.y+(y-H*.51)/s}}
function clampView(){view.x=Math.max(-1700,Math.min(1750,view.x));view.y=Math.max(-1000,Math.min(1600,view.y))}
function zoomAt(value,x=W/2,y=H*.51){const anchor=worldAt(x,y);zoom=Math.max(.52,Math.min(5.5,value));const s=scale();view.x=anchor.x-(x-W/2)/s;view.y=anchor.y-(y-H*.51)/s;clampView();$('#zoomLevel').textContent=Math.round(zoom*100)+'%';updateDistance()}
function home(){zoom=1;view={x:54,y:300};$('#zoomLevel').textContent='100%';updateDistance()}
function resize(){W=innerWidth;H=innerHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);base=Math.min((W-30)/1800,(H-150)/920);base=Math.max(.16,base);updateDistance()}
function updateDistance(){if(near){if(zoom<2.45)near=false}else if(zoom>2.7)near=true;if(mid){if(zoom<1.5)mid=false}else if(zoom>1.65)mid=true;if(!near&&!mid)bubbles.forEach(b=>b.classList.remove('visible'));$('#sceneLabel').textContent=near?'靠近，看见每一句小小的对话':mid?'每个小小的身影，都在参与':'一座不断变化的游乐场';updateInstructions()}
function updateInstructions(){const text=tool==='edit'?'点击位置添加 / 移除孩子 · 拖动仍可平移':tool==='pattern'?'点击地面放置小队 · 边缘外不能放置':near?'点击孩子观察这一刻 · 拖动探索 · 滚轮拉远':'滚轮靠近 · 拖动探索 · 暂停后可添加孩子';$('#instruction').textContent=text}
function notify(text){$('#notice').textContent=text;$('#notice').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').classList.remove('show'),2500)}
function makePerson(k,now){const p=project(k%COLS+.5,Math.floor(k/COLS)+.5);return{k,wx:p.x,wy:p.y,seed:serial++,born:now}}
function syncPeople(now,instant=false){departing=[];for(const[k,p]of people)if(!board[k]){departing.push({...p,left:now});people.delete(k)}for(let k=0;k<board.length;k++)if(board[k]&&!people.has(k))people.set(k,makePerson(k,instant?now-1000:now));dialogueKeys=dialogueKeys.filter(k=>board[k]);lastSpeechKey='';updateUI()}
function updateUI(){const count=people.size;$('#generation').textContent=`第 ${generation} 轮`;$('#population').textContent=`${count} 个孩子`;$('#playIcon').textContent=paused?'▶':'Ⅱ';$('#playText').textContent=paused?'开始':'暂停';$('#play').setAttribute('aria-label',paused?'播放演化':'暂停演化');$('#observing').hidden=!observing;updateInspector()}
function setPaused(value){paused=value;lastTick=performance.now();if(!paused){observing=false;if(tool!=='observe')setTool('observe',false)}updateUI()}
function reset(){board=new Uint8Array(COLS*ROWS);stamp(board,12,10,'blinker');generation=0;serial=0;people.clear();departing=[];selected=null;hovered=null;observing=false;dialogueKeys=[];lastTick=performance.now();syncPeople(lastTick,true);home();setTool('observe',false);notify('三个小伙伴，横一排，竖一排。')}
function next(){board=evolve(board);generation++;syncPeople(performance.now());lastTick=performance.now();if(!people.size&&!paused){paused=true;updateUI();notify('这一轮安静下来了。放个小队，再玩一次。')}}
function setTool(nextTool,pause=true){tool=nextTool;if(pause&&tool!=='observe')setPaused(true);observing=false;$('#observing').hidden=true;document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));$('#patternButton').classList.toggle('active',tool==='pattern');canvas.classList.toggle('editing',tool!=='observe');updateInstructions()}
function cellAt(x,y){const p=worldAt(x,y),g=unproject(p.x,p.y);const a=Math.floor(g.x),b=Math.floor(g.y);return a>=0&&a<COLS&&b>=0&&b<ROWS?{x:a,y:b,k:b*COLS+a}:null}
function personAt(x,y){let best=null,dist=Infinity;for(const p of people.values()){const q=screen(p.wx,p.wy);const h=47*scale(),w=Math.max(12,h*.48);if(x>q.x-w/2-4&&x<q.x+w/2+4&&y>q.y-h-7&&y<q.y+5){const d=Math.hypot(x-q.x,y-(q.y-h*.45));if(d<dist){best=p;dist=d}}}return best}
function inspect(cell){selected=cell;updateInspector()}
function updateInspector(){const panel=$('#inspector');panel.hidden=!selected;if(!selected)return;const{x,y,k}=selected,n=neighbors(board,x,y),live=!!board[k],will=n===3||(live&&n===2);$('#inspectName').textContent=`位置 ${x+1} · ${y+1}${live?' / 正在游戏':' / 空位置'}`;$('#inspectText').textContent=`周围有 ${n} 个孩子。${live?(will?'下一轮继续参与。':n<2?'邻居少于 2 个，下一轮变为空位。':'邻居多于 3 个，下一轮变为空位。'):(will?'恰好 3 个邻居，下一轮会有孩子加入。':'还不满足恰好 3 个邻居，下一轮保持空位。')}`}
function clickScene(x,y){const cell=cellAt(x,y);if(tool==='pattern'){if(!cell||!stamp(board,cell.x,cell.y,pattern)){notify('请把整个小队放在中央活动广场内。');return}syncPeople(performance.now());inspect(cell);notify('小队到位，点击「开始」看看变化。');return}if(tool==='edit'){if(!cell){notify('孩子只能放在中央的方格活动区。');return}board[cell.k]=board[cell.k]?0:1;syncPeople(performance.now());inspect(cell);return}const person=personAt(x,y);if(person&&near){setPaused(true);observing=true;selected={x:person.k%COLS,y:Math.floor(person.k/COLS),k:person.k};dialogueKeys=[person.k];updateUI();lastSpeechKey='';return}if(cell){inspect(cell);if(paused&&!board[cell.k])notify('选择「＋ 孩子」可以添加；再次点击可移除。')}else{selected=null;updateInspector()}}
function chooseDialogue(){if(!people.size)return[];let focal=selected&&board[selected.k]?people.get(selected.k):null;if(!focal){const candidates=[...people.values()].filter(p=>{const s=screen(p.wx,p.wy);return s.x>35&&s.x<W-35&&s.y>130&&s.y<H-150});focal=candidates.sort((a,b)=>Math.hypot(a.wx-view.x,a.wy-view.y)-Math.hypot(b.wx-view.x,b.wy-view.y))[0]}if(!focal)return[];const group=[...people.values()].filter(p=>Math.max(Math.abs(p.k%COLS-focal.k%COLS),Math.abs(Math.floor(p.k/COLS)-Math.floor(focal.k/COLS)))<=3);group.sort((a,b)=>a.k===focal.k?-1:b.k===focal.k?1:Math.hypot(a.wx-focal.wx,a.wy-focal.wy)-Math.hypot(b.wx-focal.wx,b.wy-focal.wy));return group.slice(0,3).map(p=>p.k)}
function rectOverlap(a,b){return a.x<b.x+b.w+10&&a.x+a.w+10>b.x&&a.y<b.y+b.h+9&&a.y+a.h+9>b.y}
function speech(){let keys=[];if(near){if(!dialogueKeys.length||!board[dialogueKeys[0]])dialogueKeys=chooseDialogue();keys=dialogueKeys.filter(k=>board[k])}else if(mid){const k=hovered?.k??selected?.k;if(k!==undefined&&board[k])keys=[k]}const signature=keys.join(',');if(signature!==lastSpeechKey){lastSpeechKey=signature;const set=phrases[(keys[0]??0)%phrases.length];keys.forEach((k,i)=>bubbles[i].textContent=set[i]);}const toolbarTop=$('.bottom-ui').getBoundingClientRect().top;const blocks=[];for(const el of[document.querySelector('header'),$('#inspector'),$('#observing'),$('.top-right')])if(!el.hidden){const r=el.getBoundingClientRect();blocks.push({x:r.x-5,y:r.y-5,w:r.width+10,h:r.height+10})}for(let i=0;i<3;i++){const bubble=bubbles[i],p=people.get(keys[i]);if(!p||(!near&&!mid)){bubble.classList.remove('visible');continue}const q=screen(p.wx,p.wy);if(q.x<12||q.x>W-12||q.y<70||q.y>toolbarTop){bubble.classList.remove('visible');continue}const w=bubble.offsetWidth||175,h=bubble.offsetHeight||42,anchorY=q.y-47*scale();let box=null;for(const[dx,dy]of[[14,-h-12],[-w-14,-h-12],[14,-h-62],[-w-14,-h-62],[24,-h-110],[-w-24,-h-110]]){const b={x:Math.max(12,Math.min(W-w-12,q.x+dx)),y:Math.max(16,anchorY+dy),w,h};if(b.y+h>toolbarTop-15)continue;if(!blocks.some(other=>rectOverlap(b,other))){box=b;break}}if(!box){bubble.classList.remove('visible');continue}bubble.style.transform=`translate(${Math.round(box.x)}px,${Math.round(box.y)}px)`;bubble.classList.add('visible');blocks.push(box)}}
function draw(now){const dpr=Math.min(devicePixelRatio||1,2);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#e5e7d9';ctx.fillRect(0,0,W,H);const s=scale();ctx.save();ctx.translate(W/2-view.x*s,H*.51-view.y*s);ctx.scale(s,s);const a=worldAt(0,0),b=worldAt(W,H);drawDistant(ctx,a.x,a.y,b.x,b.y);ctx.drawImage(world,-920,-160,world.width/1.5,world.height/1.5);
if(selected){const{x,y}=selected;for(let j=-1;j<=1;j++)for(let i=-1;i<=1;i++){const u=x+i,v=y+j;if(u<0||u>=COLS||v<0||v>=ROWS)continue;tile(ctx,u,v,!i&&!j?'#ec644c32':'#a4b49c4a','#76856a88')}}
if(hoverCell&&tool!=='observe'){const arr=tool==='pattern'?PATTERNS[pattern]:[[0,0]];for(const[dx,dy]of arr){const x=hoverCell.x+dx,y=hoverCell.y+dy;if(x>=0&&x<COLS&&y>=0&&y<ROWS)tile(ctx,x,y,'#ed49361c','#e65b4770')}}
const drawables=[...people.values(),...departing.filter(p=>now-p.left<350)];drawables.sort((a,b)=>a.wy-b.wy||a.wx-b.wx);for(const p of drawables){const age=reduced?1:Math.min(1,(now-p.born)/320);const fade=p.left===undefined?1:Math.max(0,1-(now-p.left)/350);drawPerson(ctx,p,now,.6+.4*age,Math.min(age,fade),atlas,reduced)}ctx.restore();speech()}
function animate(now){const intervals=[0,2200,1400,950,650,420,250];if(!paused&&now-lastTick>=intervals[Number($('#speed').value)])next();draw(now);requestAnimationFrame(animate)}
// Pointer-based drag and pinch. Touch drags never become accidental placements.
const pointers=new Map();let gesture=null;
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1){pinchUsed=false;gesture={id:e.pointerId,x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false}}if(pointers.size===2){const[a,b]=[...pointers.values()];pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),x:(a.x+b.x)/2,y:(a.y+b.y)/2};pinchUsed=true}canvas.classList.add('dragging')});
canvas.addEventListener('pointermove',e=>{hoverCell=cellAt(e.clientX,e.clientY);hovered=personAt(e.clientX,e.clientY);if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size>=2&&pinch){const[a,b]=[...pointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y),x=(a.x+b.x)/2,y=(a.y+b.y)/2;zoomAt(zoom*distance/Math.max(1,pinch.distance),pinch.x,pinch.y);view.x-=(x-pinch.x)/scale();view.y-=(y-pinch.y)/scale();clampView();pinch={distance,x,y};return}if(gesture&&gesture.id===e.pointerId&&!pinchUsed){const dx=e.clientX-gesture.lastX,dy=e.clientY-gesture.lastY;if(Math.hypot(e.clientX-gesture.x,e.clientY-gesture.y)>5)gesture.moved=true;if(gesture.moved){view.x-=dx/scale();view.y-=dy/scale();clampView()}gesture.lastX=e.clientX;gesture.lastY=e.clientY}});
function endPointer(e,cancel=false){if(!cancel&&gesture?.id===e.pointerId&&!gesture.moved&&!pinchUsed)clickScene(e.clientX,e.clientY);pointers.delete(e.pointerId);if(pointers.size<2)pinch=null;if(!pointers.size){gesture=null;pinchUsed=false;canvas.classList.remove('dragging')}}canvas.addEventListener('pointerup',e=>endPointer(e));canvas.addEventListener('pointercancel',e=>endPointer(e,true));canvas.addEventListener('pointerleave',()=>{hovered=null;hoverCell=null});canvas.addEventListener('wheel',e=>{e.preventDefault();zoomAt(zoom*Math.exp(-e.deltaY*(e.deltaMode===1?.025:.0013)),e.clientX,e.clientY)},{passive:false});
$('#play').onclick=()=>setPaused(!paused);$('#continue').onclick=()=>setPaused(false);$('#step').onclick=()=>{setPaused(true);observing=false;next();updateUI()};$('#reset').onclick=reset;$('#clear').onclick=()=>{setPaused(true);board.fill(0);generation=0;selected=null;observing=false;syncPeople(performance.now());notify('场地空出来了，放下第一个小队吧。')};$('#speed').oninput=()=>{$('#speedValue').textContent=['','很慢','慢慢来','轻快','快一点','更快','飞快'][$('#speed').value];lastTick=performance.now()};
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('#patternButton').onclick=()=>{const p=$('#patterns');p.hidden=!p.hidden;$('#patternButton').setAttribute('aria-expanded',String(!p.hidden))};document.querySelectorAll('[data-pattern]').forEach(b=>b.onclick=()=>{pattern=b.dataset.pattern;setTool('pattern');$('#patterns').hidden=true;$('#patternButton').setAttribute('aria-expanded','false');notify('点击中央广场，放下这个小队。')});document.addEventListener('pointerdown',e=>{if(!e.target.closest('.pattern-wrap')){$('#patterns').hidden=true;$('#patternButton').setAttribute('aria-expanded','false')}});
$('#zoomIn').onclick=()=>zoomAt(zoom*1.45);$('#zoomOut').onclick=()=>zoomAt(zoom/1.45);$('#home').onclick=home;$('#closeInspect').onclick=()=>{selected=null;observing=false;updateUI()};$('#help').onclick=()=>$('#helpDialog').showModal();$('#closeHelp').onclick=()=>$('#helpDialog').close();$('#startExploring').onclick=()=>$('#helpDialog').close();$('#helpDialog').addEventListener('click',e=>{if(e.target===$('#helpDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
document.addEventListener('keydown',e=>{if(['INPUT','BUTTON'].includes(document.activeElement.tagName)||$('#helpDialog').open)return;if(e.code==='Space'){e.preventDefault();setPaused(!paused)}if(e.key==='Escape'){selected=null;observing=false;setTool('observe',false);$('#patterns').hidden=true;updateUI()}if(e.key==='+'||e.key==='=')zoomAt(zoom*1.2);if(e.key==='-')zoomAt(zoom/1.2)});
window.addEventListener('resize',resize);document.addEventListener('visibilitychange',()=>lastTick=performance.now());resize();reset();requestAnimationFrame(animate);
